import os, csv, json, re
import numpy as np

# Quest corrected (Eval 619) inputs
P_BOUND_2E8 = 'storage/Quest/nmap/n26/noesis_data/quest_eval604_boundary_contacts_disc_level_2e8.csv'
P_TOP25_1E9 = 'storage/Quest/nmap/n26/noesis_data/quest_eval604_top25_slack_1e9.csv'
P_TOP15_1E8 = 'storage/Quest/nmap/n26/noesis_data/quest_eval604_top15_slack_1e8.csv'

# Noesis snapshot (geometry)
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'

OUT_JSON = 'storage/noesis/nmap/quest_eval604_sets_only_comparison_v4.json'

N = 26
TOL_BOUND_NOESIS_FOR_INTERIOR = 1e-8  # interior filter for Top-K refs
TOL_BOUND_FOR_JACCARD = 2e-8          # boundary Jaccard tol

# ---------------- helpers ----------------
def norm_side(s):
    if s is None: return None
    t = re.sub(r'[^a-zA-Z]', '', str(s).strip()).lower()
    if t in ('xl','xmin','xleft','left','l'):  return 'xL'
    if t in ('xr','xmax','xright','right','r'): return 'xR'
    if t in ('yb','ymin','ybottom','bottom','b'): return 'yB'
    if t in ('yt','ymax','ytop','top','t'):      return 'yT'
    if t.startswith('x') and ('min' in t or 'left' in t): return 'xL'
    if t.startswith('x') and ('max' in t or 'right' in t): return 'xR'
    if t.startswith('y') and ('min' in t or 'bottom' in t): return 'yB'
    if t.startswith('y') and ('max' in t or 'top' in t):    return 'yT'
    return None

def dictreader_with_sniff(fpath):
    with open(fpath, 'r', newline='') as f:
        sample = f.read(8192); f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=[',',';','\t','|'])
            has_header = csv.Sniffer().has_header(sample)
        except Exception:
            dialect = csv.excel
            has_header = any(c.isalpha() for c in sample)
        if has_header:
            rdr = csv.DictReader(f, dialect=dialect)
            if rdr.fieldnames:
                rdr.fieldnames = [(h.strip().lower() if isinstance(h,str) else h) for h in rdr.fieldnames]
            for row in rdr:
                yield {(k.strip().lower() if isinstance(k,str) else k): v for k,v in row.items()}
        else:
            rdr = csv.reader(f, dialect=dialect)
            for row in rdr:
                yield {str(i): cell for i,cell in enumerate(row)}

def read_boundary_disc_side(path):
    S = set()
    meta = {'exists': os.path.exists(path), 'rows': 0, 'parsed': 0}
    if not meta['exists']:
        return S, meta
    for row in dictreader_with_sniff(path):
        meta['rows'] += 1
        i_raw = row.get('disc_idx') or row.get('disc') or row.get('i') or row.get('index')
        s_raw = row.get('side') or row.get('boundary') or row.get('label') or row.get('which')
        try:
            i = int(str(i_raw).strip()) if i_raw is not None else None
        except Exception:
            i = None
        side = norm_side(s_raw)
        if i is None or side is None: 
            continue
        S.add((i, side)); meta['parsed'] += 1
    # 1-based fallback
    if S:
        idxs = [i for (i,_) in S]
        if min(idxs) >= 1 and max(idxs) <= N:
            S = set((i-1, s) for (i,s) in S)
    S = set((i,s) for (i,s) in S if 0 <= i < N and s in ('xL','xR','yB','yT'))
    return S, meta

def read_pairs_csv_robust(path):
    S = set()
    meta = {'exists': os.path.exists(path), 'rows': 0, 'parsed': 0}
    if not meta['exists']:
        return S, meta
    for row in dictreader_with_sniff(path):
        meta['rows'] += 1
        val_i = row.get('i', row.get('disc_i', row.get('disc1', row.get('a', row.get('p1')))))
        val_j = row.get('j', row.get('disc_j', row.get('disc2', row.get('b', row.get('p2')))))
        i = j = None
        try:
            if val_i is not None: i = int(str(val_i).strip())
            if val_j is not None: j = int(str(val_j).strip())
        except Exception:
            i = j = None
        if i is None or j is None:
            # fallback: parse ints from row text
            ints = [int(t) for t in re.findall(r'(?<![\d.])\d+(?![\d.])', ' '.join(str(v) for v in row.values()))]
            cand = [x for x in ints if 0 <= x < N] or [x for x in ints if 1 <= x <= N]
            if len(cand) >= 2:
                i, j = cand[-2], cand[-1]
        if i is None or j is None: 
            continue
        a,b = (i,j) if i<j else (j,i)
        if a == b: 
            continue
        S.add((a,b)); meta['parsed'] += 1
    # 1-based fallback
    if S:
        mn = min(min(i,j) for (i,j) in S)
        mx = max(max(i,j) for (i,j) in S)
        if mn >= 1 and mx <= N:
            S = set((i-1, j-1) for (i,j) in S)
    S = set((i,j) for (i,j) in S if 0 <= i < N and 0 <= j < N and i != j)
    return S, meta

def load_snapshot():
    c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
    r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    return c, r

def boundary_set_from_snapshot(c, r, tol):
    S = set()
    x = c[:,0]; y = c[:,1]
    s = {'xL': x - r, 'xR': 1.0 - x - r, 'yB': y - r, 'yT': 1.0 - y - r}
    for i in range(N):
        for side, slack in s.items():
            if slack[i] <= tol + 1e-12:
                S.add((i, side))
    return S

def boundary_discs(B):
    return set(i for (i,_) in B)

def pair_slacks(c, r):
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    return dist - (r[:,None] + r[None,:])

def topk_interior_by_slack(c, r, k, interior_discs):
    S = pair_slacks(c, r)
    pairs = []
    for i in range(N):
        for j in range(i+1, N):
            if i in interior_discs and j in interior_discs:
                pairs.append(((i,j), S[i,j]))
    pairs.sort(key=lambda t: t[1])
    return set(p for (p,_) in pairs[:k])

def seg_cross_strict(a, b, c, d, eps=0.0):
    def orient(p, q, r):
        return (q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])
    o1 = orient(a,b,c); o2 = orient(a,b,d)
    o3 = orient(c,d,a); o4 = orient(c,d,b)
    return (o1*o2 < -eps) and (o3*o4 < -eps)

def jaccard(A, B):
    if not A and not B: return 1.0, 0, 0
    inter = len(A & B); uni = len(A | B)
    return (inter/uni if uni>0 else 1.0), inter, uni

# ---------------- main ----------------
def construct_packing():
    c, r = load_snapshot()

    # Read Quest sets
    Bq, metaB = read_boundary_disc_side(P_BOUND_2E8)
    K25, meta25 = read_pairs_csv_robust(P_TOP25_1E9)
    K15, meta15 = read_pairs_csv_robust(P_TOP15_1E8)

    # Boundary @ 2e-8 Jaccard
    Bn_2e8 = boundary_set_from_snapshot(c, r, tol=TOL_BOUND_FOR_JACCARD)
    jb, ib, ub = jaccard(Bq, Bn_2e8)

    # Noesis Top-K refs (interior via Noesis boundary@1e-8)
    Bn_1e8 = boundary_set_from_snapshot(c, r, tol=TOL_BOUND_NOESIS_FOR_INTERIOR)
    interior = set(range(N)) - boundary_discs(Bn_1e8)
    Tk25_noe = topk_interior_by_slack(c, r, 25, interior)
    Tk15_noe = topk_interior_by_slack(c, r, 15, interior)
    j25, i25, u25 = jaccard(K25, Tk25_noe)
    j15, i15, u15 = jaccard(K15, Tk15_noe)

    # Dual‑tol crossing‑gate on Noesis geometry
    dual = K25 & K15
    dual_interior = [(i,j) for (i,j) in dual if i in interior and j in interior]
    cross = False; example = None
    L = len(dual_interior)
    for a_idx in range(L):
        i,j = dual_interior[a_idx]
        for b_idx in range(a_idx+1, L):
            k,l = dual_interior[b_idx]
            if len({i,j,k,l}) < 4:
                continue
            if seg_cross_strict(c[i], c[j], c[k], c[l], eps=0.0):
                cross = True; example = {'pair1': [i,j], 'pair2': [k,l]}; break
        if cross: break

    out = {
        'quest_eval_id': 619,
        'paths': {'boundary_2e8_csv': P_BOUND_2E8, 'top25_1e9_csv': P_TOP25_1E9, 'top15_1e8_csv': P_TOP15_1E8},
        'meta': {'boundary_csv': metaB, 'top25_csv': meta25, 'top15_csv': meta15},
        'boundary_jaccard_2e8': {'quest': len(Bq), 'noesis': len(Bn_2e8), 'intersection': ib, 'union': ub, 'j': jb},
        'topk_jaccards': {
            'k25_1e9': {'quest': len(K25), 'noesis': len(Tk25_noe), 'intersection': i25, 'union': u25, 'j': j25},
            'k15_1e8': {'quest': len(K15), 'noesis': len(Tk15_noe), 'intersection': i15, 'union': u15, 'j': j15}
        },
        'dual_tol_gate_on_noesis': {
            'k25': len(K25), 'k15': len(K15), 'dual_intersection': len(dual),
            'dual_interior_noesis': len(dual_interior), 'result': 'SAT' if cross else 'UNSAT',
            'example_crossing': example
        }
    }

    try:
        os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
        with open(OUT_JSON, 'w') as f:
            json.dump(out, f, indent=2)
        print('QUEST_V4_JSON:', OUT_JSON)
        print('BOUNDARY_2E8_J:', jb, 'COUNTS q/noe/int/uni=', len(Bq), len(Bn_2e8), ib, ub)
        print('TOPK_V4 J K25:', j25, 'K15:', j15, 'COUNTS K25 q/noe=', len(K25), len(Tk25_noe))
        print('GATE_V4:', out['dual_tol_gate_on_noesis'])
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    # Return baseline pack (tiny final shrink)
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
